define(["jquery"],function($){"use strict";function getViolationHtml(){return $.trim($("#proctoringpolicy_copy-message").html()||"")}function showWarning(context){let html=getViolationHtml();if(!html){return}if(context.api&&typeof context.api.showViolationMessage==="function"){context.api.showViolationMessage("copy",html)}}function initCopyPolicy(context,cfg){let limit=cfg&&cfg.limit?parseInt(cfg.limit,10):0;if(isNaN(limit)){limit=0}let warningsCount=0;function registerWarning(){if(limit>0&&warningsCount>=limit){return}warningsCount++;showWarning(context)}function isBlockedKeyEvent(e){let key=e.key?e.key.toLowerCase():"";let ctrlOrCmd=e.ctrlKey||e.metaKey;if(!ctrlOrCmd){return false}if(key==="c"||key==="v"||key==="x"||key==="a"||key==="p"){return true}return false}function handleKeydown(e){if(isBlockedKeyEvent(e)){e.preventDefault();e.stopPropagation();registerWarning()}}function handleClipboardEvent(e){e.preventDefault();e.stopPropagation();registerWarning()}function handleContextmenu(e){e.preventDefault();e.stopPropagation();registerWarning()}$(document).on("keydown.local_kopere_proctoring_copy",handleKeydown);$(document).on("copy.local_kopere_proctoring_copy",handleClipboardEvent);$(document).on("cut.local_kopere_proctoring_copy",handleClipboardEvent);$(document).on("paste.local_kopere_proctoring_copy",handleClipboardEvent);$(document).on("contextmenu.local_kopere_proctoring_copy",handleContextmenu)}return{init:function(context,cfg){initCopyPolicy(context||{},cfg||{})}}});